import{_ as g,a0 as e,w as i,s as a,ao as u,I as p,x as t,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"戴文的Linux內核專題：03 驅動程序 | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：03 驅動程序 | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：03 驅動程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：03 驅動程序 | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/03 The Linux Kernel--Drivers","title":"戴文的Linux內核專題：03 驅動程序","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/03 The Linux Kernel--Drivers.md","filePath":"[post].md"}'),l={name:"The Linux Kernel/03 The Linux Kernel--Drivers.md"};function C(d,n,P,I,m,S){const r=e("Link");return i(),a("div",null,[n[11]||(n[11]=u('<h1 id="戴文的linux內核專題-03-驅動程序" tabindex="-1">戴文的Linux內核專題：03 驅動程序 <a class="header-anchor" href="#戴文的linux內核專題-03-驅動程序" aria-label="Permalink to “戴文的Linux內核專題：03 驅動程序”">​</a></h1><p>驅動程序是使內核能夠溝通和操作硬件或協議（規則和標準）的小程序。沒有驅動程序，內核不知道如何與硬件溝通或者處理協議（內核實際上先發送指令給BIOS，然後BIOS傳給硬件）。 Linux的內核代碼在驅動程序文件夾中以源代碼的形式包含了許多驅動程序。驅動文件夾中的每個文件夾會在下面説明。在配置和​​編譯內核時，這樣有助於你瞭解驅動程序。否則，用户可能會在編譯時加入不必要的或者漏掉重要的驅動。驅動代碼通常會包含一個單行註釋來指出驅動的目的。 比如，tc的驅動代碼，有一行的註釋説是用於TURBOchannel總線。由於這些文檔，用户應該看驅動前幾行的註釋來了解它們的用途。</p><p>有幾個術語你應該已經知道，所以下面的信息應該是明白的。一個I/O設備指的是輸入/輸出設備。例如調製解調器和網卡，他們發送和接收數據。監視器是一個輸出設備 - 只有信息出來。鍵盤、鼠標和遊戲杆是數據輸入系統。存儲設備用於存儲數據，例如SD卡、硬盤、光盤、存儲卡等。CPU（處理器）是計算機的“大腦”或“心臟” ，如果沒有它，電腦就無法運作。主板則是一塊連接板上不同組件的印刷線路板。主板及各個組件是計算機的運行的基礎。許多計算機用户説主板是電腦的心臟（主板上有CPU）。主板包含了用於連接外設的端口，外設包括輸入、輸出和存儲設備。總線是主板的電路，它連接着外設。網絡設備用於兩台或多台計算機之間的連接。端口則是用户可以插入另外一台設備或一根電纜的設備，例如，用户可以將插入一根火線記憶棒插入一個火線端口；將以太網電纜插入一個以太網端口。光碟的讀取是利用激光，從可以散射或反射的激光的反射面上讀出數據，一個常見的​​光盤是DVD。許多系統説自己是32位或者64位，這指的是寄存器、地址總線或數據總線的位數。例如，在一塊64位的主板上，數據總線（組件之間的銀線）有64根並排到目的的線。存儲器地址以位(0和1)的形式在存儲器中編址，因此，一個32位存儲地址包含32個0和1來表示存儲器上的某處地址。</p><p>許多驅動程序是通用驅動程序，這意味着一個通用鍵盤驅動可以使內核可以處理幾乎所有的鍵盤。然而，有些驅動是專用驅動，像蘋果和Commodore就分別為蘋果電腦和Amiga系統製造了專門的硬件。Linux內核中已經包含了許多諸如智能手機、蘋果、Amiga系統、PS3、Android平板，和許多其他設備的驅動程序。</p><p>注意有些設備的驅動不在本目錄中。比如，射頻驅動在net和media文件夾下。</p><p><strong>accessibility</strong> - 這些驅動提供支持一些輔助設備。在Linux 3.9.4中，這個文件夾中只有一個驅動就是盲文設備驅動。</p><p><strong>acpi</strong> - 高級配置和電源接口（ACPI : Advanced Configuration and Power Interface）驅動用來管理電源使用。</p><p><strong>amba</strong> - 高級微控制器總線架構（AMBA : Advanced Microcontroller Bus Architecture）是與片上系統（SoC）的管理和互連的協議。SoC是一塊包含許多或所有必要的計算機組件的芯片。這裏的AMBA驅動讓內核能夠運行在這上面。</p><p><strong>ata</strong> - 該目錄包含PATA和SATA設備的驅動程序。串行ATA（SATA）是一種連接主機總線適配器到像硬盤那樣的存儲器的計算機總線接口。並行ATA（PATA）用於連接存儲設備，如硬盤驅動器，軟盤驅動器，光盤驅動器的標準。PATA就是我們所説的IDE。</p><p><strong>atm</strong> - 異步通信模式(ATM : Asynchronous Transfer Mode)是一種通信標準。這裏有各種接到PCI橋的驅動(他們連接到PCI總線)和以太網控制器(控制以太網通信的集成電路芯片)。</p><p><strong>auxdisplay</strong> - 這個文件夾提供了三個驅動。LCD 幀緩存（framebuffer）驅動、LCD控制器驅動和一個LCD驅動。這些驅動用於管理液晶顯示器 —— 液晶顯示器會在按壓時顯示波紋。注意:按壓會損害屏幕,所以請不要用力戳LCD顯示屏。</p><p><strong>base</strong> - 這是個重要的目錄包含了固件、系統總線、虛擬化能力等基本的驅動。</p><p><strong>bcma</strong> - 這些驅動用於使用基於AMBA協議的總線。AMBA是由博通公司開發。</p><p><strong>block</strong> - 這些驅動提供對塊設備的支持，像軟驅、SCSI磁帶、TCP網絡塊設備等等。</p><p><strong>bluetooth</strong> - 藍牙是一種安全的無線個人區域網絡標準(PANs)。藍牙驅動就在這個文件夾，它允許系統使用各種藍牙設備。例如，一個藍牙鼠標不用電纜，並且計算機有一個電子狗(小型USB接收器)。Linux系統必須能夠知道進入電子狗的信號，否則藍牙設備無法工作。</p><p><strong>bus</strong> - 這個目錄包含了三個驅動。一個轉換ocp接口協議到scp協議。一個是設備間的互聯驅動，第三個是用於處理互聯中的錯誤處理。</p><p><strong>cdrom</strong> - 這個目錄包含兩個驅動。一個是cd-rom，包括DVD和CD的讀寫。第二個是gd-rom(只讀GB光盤)，GD光盤是1.2GB容量的光盤，這像一個更大的CD或者更小的DVD。GD通常用於世嘉遊戲機中。</p><p><strong>char</strong> - 字符設備驅動就在這裏。字符設備每次傳輸數據傳輸一個字符。這個文件夾裏的驅動包括打印機、PS3閃存驅動、東芝SMM驅動和隨機數發生器驅動等。</p><p><strong>clk</strong> - 這些驅動用於系統時鐘。</p><p><strong>clocksource</strong> - 這些驅動用於作為定時器的時鐘。</p><p><strong>connector</strong> - 這些驅動使內核知道當進程fork並使用proc連接器更改UID(用户ID)、GID(組ID)和SID(會話ID)。內核需要知道什麼時候進程fork(CPU中運行多個任務)並執行。否則,內核可能會低效管理資源。</p><p><strong>cpufreq</strong> - 這些驅動改變CPU的電源能耗。</p><p><strong>cpuidle</strong> - 這些驅動用來管理空閒的CPU。一些系統使用多個CPU，其中一個驅動可以讓這些CPU負載相當。</p><p><strong>crypto</strong> - 這些驅動提供加密功能。</p><p><strong>dca</strong> - 直接緩存訪問（DCA ： Direct Cache Access）驅動允許內核訪問CPU緩存。CPU緩存就像CPU內置的RAM。CPU緩存的速度比RAM更快。然而,CPU緩存的容量比RAM小得多。CPU在這個緩存系統上存儲了最重要的和執行的代碼。</p><p><strong>devfreq</strong> - 這個驅動程序提供了一個通用的動態電壓和頻率調整(DVFS ： Generic Dynamic Voltage and Frequency Scaling)框架，可以根據需要改變CPU頻率來節約能源。這就是所謂的CPU節能。</p><p><strong>dio</strong> - 數字輸入/輸出（DIO ：Digital Input/Output）總線驅動允許內核可以使用DIO總線。</p><p><strong>dma</strong> - 直接內存訪問(DMA)驅動允許設備無需CPU直接訪問內存。這減少了CPU的負載。</p><p><strong>edac</strong> - 錯誤檢測和校正（ Error Detection And Correction）驅動幫助減少和糾正錯誤。</p><p><strong>eisa</strong> - 擴展工業標準結構總線（Extended Industry Standard Architecture）驅動提供內核對EISA總線的支持。</p><p><strong>extcon</strong> - 外部連接器（EXTernal CONnectors）驅動用於檢測設備插入時的變化。例如，extcon會檢測用户是否插入了USB驅動器。</p><p><strong>firewire</strong> - 這些驅動用於控制蘋果製造的類似於USB的火線設備。</p><p><strong>firmware</strong> - 這些驅動用於和像BIOS(計算機的基本輸入輸出系統固件)這樣的設備的固件通信。BIOS用於啓動操作系統和控制硬件與設備的固件。一些BIOS允許用户超頻CPU。超頻是使CPU運行在一個更快的速度。CPU速度以MHz(百萬赫茲)或GHz衡量。一個3.7 GHz的CPU的的速度明顯快於一個700Mhz的處理器。</p><p><strong>gpio</strong> - 通用輸入/輸出(GPIO ：General Purpose Input/Output)是可由用户控制行為的芯片的管腳。這裏的驅動就是控制GPIO。</p><p><strong>gpu</strong> - 這些驅動控制VGA、GPU和直接渲染管理(DRM ：Direct Rendering Manager )。VGA是640*480的模擬計算機顯示器或是簡化的分辨率標準。GPU是圖形處理器。DRM是一個Unix渲染系統。</p><p><strong>hid</strong> - 這驅動用於對USB人機界面設備的支持。</p><p><strong>hsi</strong> - 這個驅動用於內核訪問像Nokia N900這樣的蜂窩式調製解調器。</p><p><strong>hv</strong> - 這個驅動用於提供Linux中的鍵值對(KVP ：Key Value Pair)功能。</p><p><strong>hwmon</strong> - 硬件監控驅動用於內核讀取硬件傳感器上的信息。比如，CPU上有個温度傳感器。那麼內核就可以追蹤温度的變化並相應地調節風扇的速度。</p><p><strong>hwspinlock</strong> - 硬件轉鎖驅動允許系統同時使用兩個或者更多的處理器，或使用一個處理器上的兩個或更多的核心。</p><p><strong>i2c</strong> - I2C驅動可以使計算機用I2C協議處理主板上的低速外設。系統管理總線(SMBus ：System Management Bus)驅動管理SMBus,這是一種用於輕量級通信的two-wire總線。</p><p><strong>ide</strong> - 這些驅動用來處理像CDROM和硬盤這些PATA/IDE設備。</p><p><strong>idle</strong> - 這個驅動用來管理Intel處理器的空閒功能。</p><p><strong>iio</strong> - 工業I/O核心驅動程序用來處理數模轉換器或模數轉換器。</p><p><strong>infiniband</strong> - Infiniband是在企業數據中心和一些超級計算機中使用的一種高性能的端口。這個目錄中的驅動用來支持Infiniband硬件。</p><p><strong>input</strong> - 這裏包含了很多驅動，這些驅動都用於輸入處理，包括遊戲杆、鼠標、鍵盤、遊戲端口（舊式的遊戲杆接口）、遙控器、觸控、耳麥按鈕和許多其他的驅動。如今的操縱桿使用USB端口，但是在上世紀80、90年代，操縱桿是插在遊戲端口的。</p><p><strong>iommu</strong> - 輸入/輸出內存管理單元(IOMMU ：Input/Output Memory Management Unit)驅動用來管理內存管理單元中的IOMMU。IOMMU連接DMA IO總線到內存上。IOMMU是設備在沒有CPU幫助下直接訪問內存的橋樑。這有助於減少處理器的負載。</p><p><strong>ipack</strong> - Ipack代表的是IndustryPack。 這個驅動是一個虛擬總線,允許在載體和夾板之間操作。</p><p><strong>irqchip</strong> - 這些驅動程序允許硬件的中斷請求(IRQ)發送到處理器，暫時掛起一個正在運行的程序而去運行一個特殊的程序（稱為一箇中斷處理程序）。</p><p><strong>isdn</strong> - 這些驅動用於支持綜合業務數字網(ISDN)，這是用於同步數字傳輸語音、視頻、數據和其他網絡服務使用傳統電話網絡的電路的通信標準。</p><p><strong>leds</strong> - 用於LED的驅動。</p><p><strong>lguest</strong> - lguest用於管理客户機系統的中斷。中斷是CPU被重要任務打斷的硬件或軟件信號。CPU接着給硬件或軟件一些處理資源。</p><p><strong>macintosh</strong> - 蘋果設備的驅動在這個文件夾裏。</p><p><strong>mailbox</strong> - 這個文件夾(pl320-pci)中的驅動用於管理郵箱系統的連接。</p><p><strong>md</strong> - 多設備驅動用於支持磁盤陣列，一種多塊硬盤間共享或複製數據的系統。</p><p><strong>media</strong> - 媒體驅動提供了對收音機、調諧器、視頻捕捉卡、DVB標準的數字電視等等的支持。驅動還提供了對不同通過USB或火線端口插入的多媒體設備的支持。</p><p><strong>memory</strong> - 支持內存的重要驅動。</p><p><strong>memstick</strong> - 這個驅動用於支持Sony記憶棒。</p><p><strong>message</strong> - 這些驅動用於運行LSI Fusion MPT(一種消息傳遞技術)固件的LSI PCI芯片/適配器。LSI大規模集成，這代表每片芯片上集成了幾萬晶體管、</p><p><strong>mfd</strong> - 多用途設備(MFD)驅動提供了對可以提供諸如電子郵件、傳真、複印機、掃描儀、打印機功能的多用途設備的支持。這裏的驅動還給MFD設備提供了一個通用多媒體通信端口(MCP)層。</p><p><strong>misc</strong> - 這個目錄包含了不適合在其他目錄的各種驅動。就像光線傳感器驅動。</p><p><strong>mmc</strong> - MMC卡驅動用於處理用於MMC標準的閃存卡。</p><p><strong>mtd</strong> - 內存技術設備(MTD ：Memory technology devices)驅動程序用於Linux和閃存的交互，這就就像一層閃存轉換層。其他塊設備和字符設備的驅動程序不會以閃存設備的操作方式來做映射。儘管USB記憶卡和SD卡是閃存設備，但它們不使用這個驅動，因為他們隱藏在系統的塊設備接口後。這個驅動用於新型閃存設備的通用閃存驅動器驅動。</p><p><strong>net</strong> - 網絡驅動提供像AppleTalk、TCP和其他的網絡協議。這些驅動也提供對調製解調器、USB 2.0的網絡設備、和射頻設備的支持。</p><p><strong>nfc</strong> - 這個驅動是德州儀器的共享傳輸層之間的接口和NCI核心。</p><p><strong>ntb</strong> - 不透明的橋接驅動提供了在PCIe系統的不透明橋接。PCIe是一種高速擴展總線標準。</p><p><strong>nubus</strong> - NuBus是一種32位並行計算總線。用於支持蘋果設備。</p><p><strong>of</strong> - 此驅動程序提供設備樹中創建、訪問和解釋程序的OF助手。設備樹是一種數據結構，用於描述硬件。</p><p><strong>oprofile</strong> - 這個驅動用於從驅動到用户空間進程(運行在用户態下的應用)評測整個系統。這幫助開發人員找到性能問題</p><p><strong>parisc</strong> - 這些驅動用於HP生產的PA-RISC架構設備。PA-RISC是一種特殊指令集的處理器。</p><p><strong>parport</strong> - 並口驅動提供了Linux下的並口支持。</p><p><strong>pci</strong> - 這些驅動提供了PCI總線服務。</p><p><strong>pcmcia</strong> - 這些是筆記本的pc卡驅動</p><p><strong>pinctrl</strong> - 這些驅動用來處理引腳控制設備。引腳控制器可以禁用或啓用I/O設備。</p><p><strong>platform</strong> -這個文件夾包含了不同的計算機平台的驅動像Acer、Dell、Toshiba、IBM、Intel、Chrombooks等等。</p><p><strong>pnp</strong> - 即插即用驅動允許用户在插入一個像USB的設備後可以立即使用而不必手動配置設備。</p><p><strong>power</strong> - 電源驅動使內核可以測量電池電量，檢測充電器和進行電源管理。</p><p><strong>pps</strong> - Pulse-Per-Second驅動用來控制電流脈衝速率。這用於計時。</p><p><strong>ps3</strong> - 這是Sony的遊戲控制台驅動- PlayStation3。</p><p><strong>ptp</strong> - 圖片傳輸協議(PTP)驅動支持一種從數碼相機中傳輸圖片的協議。</p><p><strong>pwm</strong> - 脈寬調製(PWM)驅動用於控制設備的電流脈衝。主要用於控制像CPU風扇。</p><p><strong>rapidio</strong> - RapidIO驅動用於管理RapidIO架構，它是一種高性能分組交換，用於電路板上交互芯片的交互技術，也用於互相使用底板的電路板。</p><p><strong>regulator</strong> - 校準驅動用於校準電流、温度、或其他可能系統存在的校準硬件。</p><p><strong>remoteproc</strong> - 這些驅動用來管理遠程處理器。</p><p><strong>rpmsg</strong> - 這個驅動用來控制支持大量驅動的遠程處理器通訊總線(rpmsg)。這些總線提供消息傳遞設施,促進客户端驅動程序編寫自己的連接協議消息。</p><p><strong>rtc</strong> - 實時時鐘(RTC)驅動使內核可以讀取時鐘。</p><p><strong>s390</strong> - 用於31/32位的大型機架構的驅動。</p><p><strong>sbus</strong> - 用於管理基於SPARC的總線驅動。</p><p><strong>scsi</strong> - 允許內核使用SCSI標準外圍設備。例如,Linux將在與SCSI硬件傳輸數據時使用SCSI驅動。</p><p><strong>sfi</strong> -簡單固件接口(SFI)驅動允許固件發送信息表給操作系統。這些表的數據稱為SFI表。</p><p><strong>sh</strong> - 該驅動用於支持SuperHway總線。</p><p><strong>sn</strong> - 該驅動用於支持IOC3串口。</p><p><strong>spi</strong> - 這些驅動處理串行設備接口總線(SPI)，它是一個在在全雙工下運行的同步串行數據鏈路標準,。全雙工是指兩個設備可以同一時間同時發送和接收信息。雙工指的是雙向通信。設備在主/從模式下通信(取決於設備配置)。</p><p><strong>ssb</strong> - ssb(Sonics Silicon Backplane)驅動提供對在不同博通芯片和嵌入式設備上使用的迷你總線的支持。</p><p><strong>staging</strong> - 該目錄含有許多子目錄。這裏所有的驅動還需要在加入主內核前經過更多的開發工作。</p><p><strong>target</strong> - SCSI設備驅動</p><p><strong>tc</strong> - 這些驅動用於TURBOchannel，TURBOchannel是數字設備公司開發的32位開放總線。這主要用於DEC工作站。</p><p><strong>thermal</strong> - thermal驅動使CPU保持較低温度。</p><p><strong>tty</strong> - tty驅動用於管理物理終端連接。</p><p><strong>uio</strong> - 該驅動允許用户編譯運行在用户空間而不是內核空間的驅動。這使用户驅動不會導致內核崩潰。</p><p><strong>usb</strong> - USB設備允許內核使用USB端口。閃存驅動和記憶卡已經包含了固件和控制器,所以這些驅動程序允許內核使用USB接口和與USB設備。</p><p><strong>uwb</strong> - Ultra-WideBand驅動用來管理短距離，高帶寬通信的超低功耗的射頻設備</p><p><strong>vfio</strong> - 允許設備訪問用户空間的VFIO驅動。</p><p><strong>vhost</strong> - 這是用於宿主內核中的virtio服務器驅動。用於虛擬化中。</p><p><strong>video</strong> - 這是用來管理顯卡和監視器的視頻驅動。</p><p><strong>virt</strong> - 這些驅動用來虛擬化。</p><p><strong>virtio</strong> - 這個驅動用來在虛擬PCI設備上使用virtio設備。用於虛擬化中。</p><p><strong>vlynq</strong> - 這個驅動控制着由德州儀器開發的專有接口。這些都是寬帶產品，像WLAN和調製解調器，VOIP處理器，音頻和數字媒體信號處理芯片。</p><p><strong>vme</strong> - WMEbus最初是為摩托羅拉68000系列處理器開發的總線標準</p><p><strong>w1</strong> - 這些驅動用來控制one-wire總線。</p><p><strong>watchdog</strong> - 該驅動管理看門狗定時器，這是一個可以用來檢測和恢復異常的定時器。</p><p><strong>xen</strong> - 該驅動是Xen管理程序系統。這是個允許用户運行多個操作系統在一台計算機的軟件或硬件。這意味着xen的代碼將允許用户在同一時間的一台計算機上運行兩個或更多的Linux系統。用户也可以在Linux上運行Windows、Solaris、FreeBSD、或其他操作系統。</p><p><strong>zorro</strong> - 該驅動提供Zorro Amiga總線支持。</p><hr>',114)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),o(r,{href:"http://www.linux.org/threads/the-linux-kernel-drivers.4205/"},{default:s(()=>[...n[0]||(n[0]=[t("http://www.linux.org/threads/the-linux-kernel-drivers.4205/",-1)])]),_:1})]),p("p",null,[n[4]||(n[4]=t("譯者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:s(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:s(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[n[8]||(n[8]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:s(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const x=g(l,[["render",C]]);export{D as __pageData,x as default};
